#[test]
fn an_unconfigured_gate_names_the_missing_secret_and_the_two_causes_differ() {
    let no_key = gate::not_configured(gate::MissingSecret::SharedKey);
    let no_broker = gate::not_configured(gate::MissingSecret::BrokerOrigin);
    // The enum names exactly the two handles an operator sets.
    assert_eq!(gate::MissingSecret::SharedKey.handle(), gate::SSO_SECRET);
    assert_eq!(gate::MissingSecret::BrokerOrigin.handle(), gate::SSO_BROKER_ORIGIN);
    // Documentation and runbooks quote this prefix; it stays.
    assert!(no_key.starts_with("sign-in is not configured"));
    assert!(no_broker.starts_with("sign-in is not configured"));
    assert!(no_key.contains(gate::SSO_SECRET) && !no_key.contains(gate::SSO_BROKER_ORIGIN));
    assert!(no_broker.contains(gate::SSO_BROKER_ORIGIN) && !no_broker.contains(gate::SSO_SECRET));
    assert_ne!(no_key, no_broker);
    // A present but malformed broker origin takes the same branch, so the
    // message has to cover it.
    assert!(no_broker.contains("https://"));
}

