/// The broker a client trusts is a deployment secret; only a bare `https://`
/// origin is accepted, because it becomes the prefix of every redirect.
#[test]
fn broker_origin_accepts_only_a_bare_https_origin() {
    use crate::ferrite_sso::gate::parse_broker_origin;
    assert_eq!(parse_broker_origin("https://login.example.test").as_deref(), Some("https://login.example.test"));
    assert_eq!(parse_broker_origin(" https://login.example.test/ ").as_deref(), Some("https://login.example.test"));
    assert_eq!(parse_broker_origin("https://login.example.test:8443").as_deref(), Some("https://login.example.test:8443"));
    for refused in [
        "",
        "https://",
        "http://login.example.test",
        "HTTPS://login.example.test",
        "https://login.example.test/sso",
        "https://login.example.test?x=1",
        "https://login.example.test#f",
        "https://user@login.example.test",
        "https://:8443",
        "https://login.example.test evil",
        "login.example.test",
    ] {
        assert_eq!(parse_broker_origin(refused), None, "{refused:?} must be refused");
    }
}

fn token_from(location: &str) -> String {
    let query = location.split_once('?').unwrap().1;
    return_to::query_value(query, "a").unwrap()
}

#[test]
fn registry_rejects_ambiguous_or_non_exact_tables() {
    assert!(SsoRegistry::new(CLIENTS).validate().is_ok());

    static DUPLICATE_ID: &[SsoClient] = &[
        SsoClient {
            client_id: "docs",
            origin: "https://a.example.test",
        },
        SsoClient {
            client_id: "docs",
            origin: "https://b.example.test",
        },
    ];
    assert!(SsoRegistry::new(DUPLICATE_ID).validate().is_err());

    // Two audiences on one origin would let each redeem the other's
    // assertions, silently undoing audience binding.
    static DUPLICATE_ORIGIN: &[SsoClient] = &[
        SsoClient {
            client_id: "a",
            origin: "https://same.example.test",
        },
        SsoClient {
            client_id: "b",
            origin: "https://same.example.test",
        },
    ];
    assert!(SsoRegistry::new(DUPLICATE_ORIGIN).validate().is_err());

    static INSECURE: &[SsoClient] = &[SsoClient {
        client_id: "a",
        origin: "http://plain.example.test",
    }];
    assert!(SsoRegistry::new(INSECURE).validate().is_err());

    static WITH_PATH: &[SsoClient] = &[SsoClient {
        client_id: "a",
        origin: "https://host.example.test/path",
    }];
    assert!(SsoRegistry::new(WITH_PATH).validate().is_err());

    // finding_9c96f8582965775b: non-authority syntax, and equal origins spelled differently.
    for origin in ["https://Docs.example.test", "https://docs.example.test:443", "https://host.example?x=1", "https://host.example#f", "https://user@host.example"] {
        let clients: &'static [SsoClient] = Box::leak(Box::new([SsoClient { client_id: "a", origin }]));
        assert!(SsoRegistry::new(clients).validate().is_err(), "{origin}");
    }
}

#[test]
fn a_full_round_trip_signs_the_person_in() {
    let outcome = start(
        &broker(),
        Some("subject-42"),
        "client_id=docs&return_to=%2Fguides",
        NOW,
    )
    .unwrap();
    let StartOutcome::Redirect {
        location,
        client_id,
    } = outcome
    else {
        panic!("expected a redirect");
    };
    assert_eq!(client_id, "docs");
    assert!(location.starts_with("https://docs.example.test/_sso/callback?a="));

    let query = location.split_once('?').unwrap().1;
    match redeem(&client("docs"), query, NOW + 1_000, fresh()) {
        Redemption::Accept {
            subject, return_to, ..
        } => {
            assert_eq!(subject, "subject-42");
            assert_eq!(return_to, "/guides");
        }
        other => panic!("expected acceptance, got {other:?}"),
    }
}

