#[test]
fn the_subject_cannot_be_forged_by_editing_the_token() {
    let key = AssertionKey::from_secret(SECRET);
    let (_, token) = key
        .mint("real-subject", "docs", NOW, DEFAULT_TTL_MS)
        .unwrap();
    // Swap the hex subject for another of the same length: the MAC no longer
    // covers the bytes presented. This is the whole reason for signing.
    let forged = token.replacen(
        &crate::crypto_kernel::hex_encode(b"real-subject"),
        &crate::crypto_kernel::hex_encode(b"admin-user00"),
        1,
    );
    assert_ne!(forged, token);
    assert_eq!(
        key.verify(&forged, "docs", NOW),
        Err(AssertionError::BadSignature)
    );
}

