#[test]
fn an_assertion_is_single_use() {
    let outcome = start(&broker(), Some("subject-42"), "client_id=docs", NOW).unwrap();
    let StartOutcome::Redirect { location, .. } = outcome else {
        panic!("expected a redirect");
    };
    let query = location.split_once('?').unwrap().1;

    let mut burned: Vec<String> = Vec::new();
    let mut sink = |nonce: &str, _expiry: u64| {
        let seen = burned.iter().any(|value| value == nonce);
        if !seen {
            burned.push(nonce.to_string());
        }
        seen
    };

    assert!(matches!(
        redeem(&client("docs"), query, NOW + 1_000, &mut sink),
        Redemption::Accept { .. }
    ));
    // The same assertion, replayed inside its TTL.
    match redeem(&client("docs"), query, NOW + 2_000, &mut sink) {
        Redemption::Refuse { reason } => assert!(reason.contains("already redeemed")),
        other => panic!("expected replay refusal, got {other:?}"),
    }
}

