#[test]
fn return_to_accepts_only_in_application_paths() {
    for good in ["/", "/guides", "/a/b/c", "/search?q=ferrite&page=2"] {
        assert!(is_safe_return_to(good), "rejected {good:?}");
    }
    for bad in [
        "https://evil.example",    // absolute
        "//evil.example",          // scheme-relative
        "/\\evil.example",         // backslash folding
        "/path#frag",              // fragment
        "/a/../../etc",            // dot segments
        "/a%2f..%2fb",             // encoded separators
        "/_sso/callback",          // sso prefix
        "relative",                // not absolute
        "/\u{0}null",              // control character
        "/\u{fc}ber",              // raw non-ASCII (finding_480addeac5036033)
        "/a b",                    // raw space
    ] {
        assert!(!is_safe_return_to(bad), "accepted {bad:?}");
    }
    assert!(!is_safe_return_to(&format!(
        "/{}",
        "a".repeat(MAX_RETURN_TO_BYTES)
    )));
}

