#[test]
fn a_tampered_return_to_cannot_redirect_off_site() {
    // return_to rides outside the MAC by design, so the client re-validates
    // it. Rewriting it in flight must not produce an off-site Location.
    let outcome = start(
        &broker(),
        Some("subject-42"),
        "client_id=docs&return_to=%2Fguides",
        NOW,
    )
    .unwrap();
    let StartOutcome::Redirect { location, .. } = outcome else {
        panic!("expected a redirect");
    };
    let token = token_from(&location);
    let tampered = format!(
        "a={}&return_to={}",
        return_to::query_encode(&token),
        return_to::query_encode("https://evil.example/steal"),
    );
    match redeem(&client("docs"), &tampered, NOW + 1_000, fresh()) {
        Redemption::Accept {
            subject, return_to, ..
        } => {
            assert_eq!(subject, "subject-42");
            assert_eq!(return_to, "/");
        }
        other => panic!("expected acceptance with a safe path, got {other:?}"),
    }
}

