/// A too-distant expiry must not be reported as malformed. The token parsed
/// and its MAC verified, so telling the reader it was malformed sends them
/// to check their hex encoding when the fault is a TTL they chose.
#[test]
fn a_future_expiry_names_itself_rather_than_claiming_malformed() {
    let key = AssertionKey::from_secret("shared");
    let now = 1_000_000_000_000u64;
    let (_assertion, token) = key
        .mint("someone", "atlas", now, DEFAULT_TTL_MS * 10)
        .expect("minting succeeds");
    assert_eq!(
        key.verify(&token, "atlas", now),
        Err(AssertionError::ExpiryTooDistant)
    );

    // The ordinary TTL still verifies, so the guard has not swallowed the
    // honest case.
    let (_assertion, ok) = key
        .mint("someone", "atlas", now, DEFAULT_TTL_MS)
        .expect("minting succeeds");
    assert!(key.verify(&ok, "atlas", now).is_ok());
}

// ── A minted session cookie is the one the gate verifies ────────────────────

#[tokio::test]
async fn a_minted_session_cookie_pair_is_what_signed_in_verifies() {
    use crate::ferrite_sso::gate::{session_cookie_pair, signed_in, SSO_SECRET};
    let env = ferrite_app_test::TestHarness::new().with_store("nonces").manual_clock(NOW).build().await;
    let mut payload = env.payload().clone();
    payload.secrets.insert(SSO_SECRET.into(), SECRET.into());
    let ctx = ferrite_app::AppContext::with_clock(payload, env.clock());

    let pair = session_cookie_pair(SECRET, "docs", "local-test-owner", NOW).expect("a cookie is minted");
    assert!(pair.starts_with("__Host-ferrite_app_session="), "{pair}");

    let mut req = ferrite_app_test::ingress::get("/anything");
    req.headers.push(("cookie".into(), pair.clone()));
    let claims = signed_in(&ctx, &req, "docs").await.expect("the minted cookie signs the caller in");
    assert_eq!(claims.user, "local-test-owner");
    assert!(signed_in(&ctx, &req, "shop").await.is_none(), "another property's session is refused");

    let mut forged = ferrite_app_test::ingress::get("/anything");
    forged.headers.push(("cookie".into(), format!("{}x", pair)));
    assert!(signed_in(&ctx, &forged, "docs").await.is_none(), "an edited cookie is refused");

    let other = session_cookie_pair("another-secret-entirely", "docs", "local-test-owner", NOW).unwrap();
    let mut wrong_key = ferrite_app_test::ingress::get("/anything");
    wrong_key.headers.push(("cookie".into(), other));
    assert!(signed_in(&ctx, &wrong_key, "docs").await.is_none(), "a cookie under another secret is refused");
}

/// A session minted under the shared secret alone, as every gate did before
/// sessions were bound to their property.
fn legacy_cookie(subject: &str) -> String {
    let token = crate::ferrite_sso::SessionService::from_secret(SECRET, 60_000).issue(subject, 0, NOW).unwrap();
    format!("__Host-ferrite_app_session={}", token.token)
}

fn signed_ctx(env: &ferrite_app_test::TestEnv) -> ferrite_app::AppContext {
    let mut payload = env.payload().clone();
    payload.secrets.insert(gate::SSO_SECRET.into(), SECRET.into());
    payload.secrets.insert(gate::SSO_BROKER_ORIGIN.into(), "https://login.example.test".into());
    ferrite_app::AppContext::with_clock(payload, env.clock())
}

fn page(path: &str, cookie: &str) -> ferrite_app::IngressRequest {
    let mut req = ferrite_app_test::ingress::get(path);
    req.headers.push(("accept".into(), "text/html".into()));
    req.headers.push(("cookie".into(), cookie.to_string()));
    req
}

fn set_cookie(reply: &ferrite_app::IngressReply) -> Option<String> {
    reply
        .headers
        .iter()
        .find(|(name, _)| name.eq_ignore_ascii_case("set-cookie"))
        .map(|(_, value)| value.split(';').next().unwrap_or("").to_string())
}

/// finding_8299ff02afed7d07 and the 11 November lead
/// `ferrite-sso:gate:unscoped-session-unbound-and-unrevocable`: a session
/// signed in at one property was accepted by every other, and outlived
/// sign-out.
#[tokio::test]
async fn a_session_is_bound_to_its_property_and_ends_at_sign_out() {
    let env = ferrite_app_test::TestHarness::new().with_store("nonces").manual_clock(NOW).build().await;
    let ctx = signed_ctx(&env);
    let (_, token) = AssertionKey::from_secret(SECRET).mint("google:42:a@example.test", "docs", NOW, DEFAULT_TTL_MS).unwrap();
    let mut callback = ferrite_app_test::ingress::get(&format!("/_sso/callback?a={}", return_to::query_encode(&token)));
    callback.headers.push(("sec-fetch-mode".into(), "navigate".into()));
    let reply = gate(&ctx, &callback, "docs").await.unwrap();
    assert_eq!(reply.status, 303);
    let cookie = set_cookie(&reply).expect("the callback signs in");

    let docs = page("/private", &cookie);
    assert!(gate(&ctx, &docs, "docs").await.is_none(), "the session admits where it was minted");
    assert_eq!(gate::signed_in(&ctx, &docs, "docs").await.unwrap().user, "google:42:a@example.test");
    let shop = page("/private", &cookie);
    let refused = gate(&ctx, &shop, "shop").await.expect("another property refuses it");
    assert_eq!(refused.status, 303, "it is sent to sign in, not admitted");
    assert!(gate::signed_in(&ctx, &shop, "shop").await.is_none());

    // A sign-out link from another site or a prefetch signs nobody out.
    let mut planted = ferrite_app_test::ingress::get("/_sso/logout");
    planted.headers.push(("cookie".into(), cookie.clone()));
    planted.headers.push(("sec-fetch-site".into(), "cross-site".into()));
    assert_eq!(gate(&ctx, &planted, "docs").await.unwrap().status, 403);
    let mut sibling = planted.clone();
    sibling.headers.retain(|(name, _)| name != "sec-fetch-site");
    sibling.headers.push(("sec-fetch-site".into(), "same-site".into()));
    assert_eq!(gate(&ctx, &sibling, "docs").await.unwrap().status, 403);
    let mut prefetch = ferrite_app_test::ingress::get("/_sso/logout");
    prefetch.headers.push(("cookie".into(), cookie.clone()));
    prefetch.headers.push(("sec-purpose".into(), "prefetch".into()));
    assert_eq!(gate(&ctx, &prefetch, "docs").await.unwrap().status, 403);
    assert!(gate(&ctx, &docs, "docs").await.is_none(), "the session survives a refused sign-out");

    // The same person signed in on another device.
    let elsewhere = gate::session_cookie_pair(SECRET, "docs", "google:42:a@example.test", NOW).unwrap();

    // The visitor's own sign-out ends the session, wherever the cookie is.
    let mut logout = ferrite_app_test::ingress::get("/_sso/logout");
    logout.headers.push(("cookie".into(), cookie.clone()));
    logout.headers.push(("sec-fetch-site".into(), "same-origin".into()));
    let out = gate(&ctx, &logout, "docs").await.unwrap();
    assert_eq!(out.status, 303);
    assert!(set_cookie(&out).is_some_and(|pair| pair == "__Host-ferrite_app_session="), "the cookie is cleared");
    assert!(gate::signed_in(&ctx, &docs, "docs").await.is_none(), "a copied cookie stops working at sign-out");
    assert!(gate(&ctx, &docs, "docs").await.is_some());
    assert!(gate(&ctx, &page("/private", &elsewhere), "docs").await.is_none(), "another device stays signed in");

    // Signing in again works.
    let (_, token) = AssertionKey::from_secret(SECRET).mint("google:42:a@example.test", "docs", NOW, DEFAULT_TTL_MS).unwrap();
    let mut again = ferrite_app_test::ingress::get(&format!("/_sso/callback?a={}", return_to::query_encode(&token)));
    again.headers.push(("sec-fetch-mode".into(), "navigate".into()));
    let fresh = set_cookie(&gate(&ctx, &again, "docs").await.unwrap()).expect("signs in again");
    assert!(gate(&ctx, &page("/private", &fresh), "docs").await.is_none());
}

#[tokio::test]
async fn unbound_and_overlong_sessions_are_refused() {
    let env = ferrite_app_test::TestHarness::new().with_store("nonces").manual_clock(NOW).build().await;
    let ctx = signed_ctx(&env);
    // Minted under the shared secret alone: the cookie every property accepted.
    let legacy = page("/private", &legacy_cookie("google:42"));
    assert!(gate(&ctx, &legacy, "docs").await.is_some());
    assert!(gate::signed_in(&ctx, &legacy, "docs").await.is_none());
    // Minted for this property, but with a day's lifetime.
    let long = crate::ferrite_sso::SessionService::for_client(SECRET, "docs", 24 * 60 * 60 * 1_000)
        .issue("google:42", 0, NOW)
        .unwrap();
    let long = page("/private", &format!("__Host-ferrite_app_session={}", long.token));
    assert!(gate::signed_in(&ctx, &long, "docs").await.is_none());
}

/// A session is renewed through the broker, which rechecks its access list:
/// a navigation late in its life is sent there with the old cookie cleared,
/// an API call still passes, and a session past its hour passes nothing.
#[tokio::test]
async fn a_late_session_is_renewed_through_the_broker() {
    let env = ferrite_app_test::TestHarness::new().with_store("nonces").manual_clock(NOW).build().await;
    let ctx = signed_ctx(&env);
    let minted_at = |ago: u64| {
        let token = gate::client_sessions(SECRET, "docs").issue("google:42", 0, NOW - ago).unwrap();
        format!("__Host-ferrite_app_session={}", token.token)
    };
    let fresh = minted_at(gate::SESSION_RENEW_AFTER_MS - 1);
    assert!(gate(&ctx, &page("/private", &fresh), "docs").await.is_none());
    assert!(gate::open_gate(&ctx, &page("/private", &fresh), "docs").await.is_none());

    let late = minted_at(gate::SESSION_RENEW_AFTER_MS + 1);
    for reply in [
        gate(&ctx, &page("/private", &late), "docs").await.unwrap(),
        gate::open_gate(&ctx, &page("/private", &late), "docs").await.unwrap(),
    ] {
        assert_eq!(reply.status, 303);
        let location = reply.headers.iter().find(|(n, _)| n == "location").unwrap().1.clone();
        assert!(location.starts_with("https://login.example.test/sso/start?client_id=docs"), "{location}");
        assert_eq!(set_cookie(&reply).as_deref(), Some("__Host-ferrite_app_session="));
    }
    let mut api = ferrite_app_test::ingress::get("/api/items");
    api.headers.push(("cookie".into(), late.clone()));
    assert!(gate(&ctx, &api, "docs").await.is_none(), "a machine call is never redirected");

    let lapsed = minted_at(gate::SESSION_TTL_MS);
    let mut api = ferrite_app_test::ingress::get("/api/items");
    api.headers.push(("cookie".into(), lapsed));
    assert_eq!(gate(&ctx, &api, "docs").await.unwrap().status, 401);
}

// Scoped API regressions live in the package so every consumer carries them.
#[tokio::test]
async fn scoped_cookies_reject_legacy_and_other_clients() {
    let env=ferrite_app_test::TestHarness::new().with_store("nonces").manual_clock(NOW).build().await;
    let mut payload=env.payload().clone();payload.secrets.insert("sso_shared_secret".into(),SECRET.into());
    let ctx=ferrite_app::AppContext::with_clock(payload,env.clock());
    for pair in [legacy_cookie("google:42"),super::scoped_session_cookie_pair(SECRET,"other","google:42",0,NOW).unwrap()] {
        let mut req=ferrite_app_test::ingress::get("/");req.headers.push(("cookie".into(),pair));
        assert!(super::scoped_signed_in(&ctx,&req,"docs").await.unwrap().is_none());
    }
    let pair=super::scoped_session_cookie_pair(SECRET,"docs","google:42:new@example.test",0,NOW).unwrap();
    let mut req=ferrite_app_test::ingress::get("/");req.headers.push(("cookie".into(),pair));
    assert_eq!(super::scoped_signed_in(&ctx,&req,"docs").await.unwrap().unwrap().user,"google:42");
}

#[tokio::test]
async fn scoped_logout_fences_the_old_cookie_and_requires_exact_origin() {
    let env=ferrite_app_test::TestHarness::new().with_store("nonces").manual_clock(NOW).build().await;
    let mut payload=env.payload().clone();payload.secrets.insert("sso_shared_secret".into(),SECRET.into());payload.secrets.insert("sso_public_origin".into(),"https://docs.example.test".into());payload.secrets.insert("sso_broker_origin".into(),"https://login.example.test".into());
    let ctx=ferrite_app::AppContext::with_clock(payload,env.clock());
    let pair=super::scoped_session_cookie_pair(SECRET,"docs","google:42",0,NOW).unwrap();
    let mut req=ferrite_app_test::ingress::post("/_sso/logout",b"");req.headers.push(("cookie".into(),pair));
    assert_eq!(super::scoped_gate(&ctx,&req,"docs").await.unwrap().status,403);
    assert!(super::scoped_signed_in(&ctx,&req,"docs").await.unwrap().is_some());
    req.headers.push(("origin".into(),"https://docs.example.test".into()));
    assert_eq!(super::scoped_gate(&ctx,&req,"docs").await.unwrap().status,303);
    assert!(super::scoped_signed_in(&ctx,&req,"docs").await.unwrap().is_none());
}

