#[tokio::test]
async fn scoped_fragments_never_admit_or_clear_legacy_or_scoped_sessions() {
    let env=ferrite_app_test::TestHarness::new().with_store("nonces").manual_clock(NOW).build().await;
    let mut payload=env.payload().clone();
    payload.secrets.insert("sso_shared_secret".into(),SECRET.into());
    payload.secrets.insert("sso_public_origin".into(),"https://docs.example.test".into());
    payload.secrets.insert("sso_broker_origin".into(),"https://login.example.test".into());
    let ctx=ferrite_app::AppContext::with_clock(payload,env.clock());
    let scoped=super::scoped_session_cookie_pair(SECRET,"docs","google:42",0,NOW).unwrap();
    let legacy=legacy_cookie("google:42");
    for path in ["/_sso/callback#?a=x","/_sso/callback#x?","/_sso/callback#/overview?q","/_sso/logout#fragment","/_sso/logout#?x","/_sso/callback?a=x#fragment"] {
        for pair in [&scoped,&legacy] {
            for method in ["GET","POST"] {
                let mut req=ferrite_app_test::ingress::get(path);req.method=method.into();
                req.headers.push(("cookie".into(),pair.clone()));req.headers.push(("origin".into(),"https://docs.example.test".into()));
                let reply=super::scoped_gate(&ctx,&req,"docs").await.expect("fragment must never fall through");
                assert_eq!(reply.status,400,"{path} {method}");
                assert!(!reply.headers.iter().any(|(name,_)|name.eq_ignore_ascii_case("set-cookie")));
            }
        }
    }
    let mut req=ferrite_app_test::ingress::get("/private");req.headers.push(("cookie".into(),scoped));
    assert!(super::scoped_signed_in(&ctx,&req,"docs").await.unwrap().is_some());
}

#[tokio::test]
async fn scoped_callback_requires_assertion_even_with_existing_cookies() {
    let env=ferrite_app_test::TestHarness::new().with_store("nonces").manual_clock(NOW).build().await;
    let mut payload=env.payload().clone();
    payload.secrets.insert("sso_shared_secret".into(),SECRET.into());
    payload.secrets.insert("sso_public_origin".into(),"https://docs.example.test".into());
    payload.secrets.insert("sso_broker_origin".into(),"https://login.example.test".into());
    let ctx=ferrite_app::AppContext::with_clock(payload,env.clock());
    for pair in [legacy_cookie("google:42"),super::scoped_session_cookie_pair(SECRET,"docs","google:42",0,NOW).unwrap()] {
        let mut req=ferrite_app_test::ingress::get("/_sso/callback?a=invalid");req.headers.push(("cookie".into(),pair));
        let reply=super::scoped_gate(&ctx,&req,"docs").await.expect("invalid callback cannot admit a cookie");
        assert!(reply.status>=400);assert!(!reply.headers.iter().any(|(name,_)|name.eq_ignore_ascii_case("set-cookie")));
    }
    let (_,token)=AssertionKey::from_secret(SECRET).mint("google:42","docs",NOW,DEFAULT_TTL_MS).unwrap();
    let mut req=ferrite_app_test::ingress::get(&format!("/_sso/callback?a={}",return_to::query_encode(&token)));
    req.headers.push(("cookie".into(),legacy_cookie("google:99")));
    let reply=super::scoped_gate(&ctx,&req,"docs").await.unwrap();assert_eq!(reply.status,303);
    let pair=reply.headers.iter().find(|(name,_)|name.eq_ignore_ascii_case("set-cookie")).unwrap().1.split(';').next().unwrap().to_owned();
    let mut authenticated=ferrite_app_test::ingress::get("/private");authenticated.headers.push(("cookie".into(),pair));
    assert!(super::signed_in(&ctx,&authenticated,"shop").await.is_none());
    assert_eq!(super::scoped_signed_in(&ctx,&authenticated,"docs").await.unwrap().unwrap().user,"google:42");
}

