// ── An open property admits signed-out visitors and keeps its sign-in paths ──

#[tokio::test]
async fn the_open_gate_admits_signed_out_visitors_and_still_answers_its_own_paths() {
    use crate::ferrite_sso::gate::{open_gate, SSO_BROKER_ORIGIN, SSO_SECRET};
    let env = ferrite_app_test::TestHarness::new().with_store("nonces").manual_clock(NOW).build().await;
    let mut payload = env.payload().clone();
    payload.secrets.insert(SSO_SECRET.into(), SECRET.into());
    payload.secrets.insert(SSO_BROKER_ORIGIN.into(), "https://login.example.test".into());
    let ctx = ferrite_app::AppContext::with_clock(payload, env.clock());

    let mut page = ferrite_app_test::ingress::get("/");
    page.headers.push(("accept".into(), "text/html".into()));
    assert!(open_gate(&ctx, &page, "demo").await.is_none(), "a browser reaches the page");
    let api = ferrite_app_test::ingress::get("/api/items");
    assert!(open_gate(&ctx, &api, "demo").await.is_none(), "a machine caller reaches the api");
    assert!(gate(&ctx, &api, "demo").await.is_some(), "the closed gate still refuses it");

    let health = ferrite_app_test::ingress::get("/healthz");
    assert_eq!(open_gate(&ctx, &health, "demo").await.expect("the gate answers").status, 200);
    let logout = ferrite_app_test::ingress::get("/_sso/logout");
    assert_eq!(open_gate(&ctx, &logout, "demo").await.expect("sign-out is answered").status, 303);
    for path in ["/_sso/logout#?x", "/_sso/callback#?a=x", "/page#frag"] {
        let req = ferrite_app_test::ingress::get(path);
        assert_eq!(open_gate(&ctx, &req, "demo").await.expect("refused").status, 400, "{path}");
        assert_eq!(gate(&ctx, &req, "demo").await.expect("refused").status, 400, "{path}");
    }
    let callback = ferrite_app_test::ingress::get("/_sso/callback");
    assert!(open_gate(&ctx, &callback, "demo").await.is_some(), "the callback is still the gate's");
}

#[tokio::test]
async fn weak_secrets_refuse_and_callbacks_are_navigation_only_and_never_swap_sessions() {
    use crate::ferrite_sso::gate::{session_cookie_pair, signed_in, SSO_BROKER_ORIGIN, SSO_SECRET};
    let env = ferrite_app_test::TestHarness::new().with_store("nonces").manual_clock(NOW).build().await;
    for weak in ["", "   ", "short-secret"] {
        let mut payload = env.payload().clone();
        payload.secrets.insert(SSO_SECRET.into(), weak.into());
        payload.secrets.insert(SSO_BROKER_ORIGIN.into(), "https://login.example.test".into());
        let ctx = ferrite_app::AppContext::with_clock(payload, env.clock());
        let health = ferrite_app_test::ingress::get("/healthz");
        assert_eq!(gate(&ctx, &health, "demo").await.unwrap().status, 503, "{weak:?}");
        let mut req = ferrite_app_test::ingress::get("/");
        req.headers.push(("cookie".into(), session_cookie_pair(weak, "demo", "google:1", NOW).unwrap()));
        assert!(signed_in(&ctx, &req, "demo").await.is_none(), "{weak:?}");
    }

    let mut payload = env.payload().clone();
    payload.secrets.insert(SSO_SECRET.into(), SECRET.into());
    payload.secrets.insert(SSO_BROKER_ORIGIN.into(), "https://login.example.test".into());
    let ctx = ferrite_app::AppContext::with_clock(payload, env.clock());
    let callback = |token: &str| {
        ferrite_app_test::ingress::get(&format!("/_sso/callback?a={}", return_to::query_encode(token)))
    };
    let mint = |subject: &str| AssertionKey::from_secret(SECRET).mint(subject, "demo", NOW, DEFAULT_TTL_MS).unwrap().1;

    // A subresource planted by another site cannot redeem an assertion.
    let mut img = callback(&mint("google:mallory"));
    img.headers.push(("sec-fetch-mode".into(), "no-cors".into()));
    img.headers.push(("sec-fetch-dest".into(), "image".into()));
    assert_eq!(gate(&ctx, &img, "demo").await.unwrap().status, 403);
    let mut post = callback(&mint("google:mallory"));
    post.method = "POST".into();
    assert_eq!(gate(&ctx, &post, "demo").await.unwrap().status, 405);

    // A browser already signed in keeps its own session.
    let mut swap = callback(&mint("google:mallory"));
    swap.headers.push(("cookie".into(), session_cookie_pair(SECRET, "demo", "google:alice", NOW).unwrap()));
    let reply = gate(&ctx, &swap, "demo").await.unwrap();
    assert_eq!(reply.status, 303);
    assert!(!reply.headers.iter().any(|(name, _)| name.eq_ignore_ascii_case("set-cookie")));

    // A real navigation still signs in.
    let mut nav = callback(&mint("google:alice"));
    nav.headers.push(("sec-fetch-mode".into(), "navigate".into()));
    nav.headers.push(("sec-fetch-dest".into(), "document".into()));
    let reply = gate(&ctx, &nav, "demo").await.unwrap();
    assert_eq!(reply.status, 303);
    assert!(reply.headers.iter().any(|(name, _)| name.eq_ignore_ascii_case("set-cookie")));
}

#[test]
fn encoded_dot_segments_are_not_safe_return_paths() {
    for value in ["/%2e/_sso/logout", "/mount/%2E%2e/other", "/a/%2e"] {
        assert!(!is_safe_return_to(value), "{value}");
    }
    assert!(is_safe_return_to("/a/b.c?x=1"));
}
